package com.tickethub.dto;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.Future;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/** Body of create show. Seats are generated by the service, so the client does not send them. */
public record ShowRequest(
        @NotNull(message = "Movie id is required")
        Long movieId,

        @NotBlank(message = "Theatre name is required")
        @Size(max = 150, message = "Theatre name must be at most 150 characters")
        String theatreName,

        @NotNull(message = "Start time is required")
        @Future(message = "Start time must be in the future")
        LocalDateTime startTime,

        @NotNull(message = "Price is required")
        @DecimalMin(value = "0.01", message = "Price must be at least 0.01")
        @Digits(integer = 8, fraction = 2, message = "Price must have at most 8 digits and 2 decimal places")
        BigDecimal price
) {
}
